parent = {('ann','bob'), ('bob','cat')}
def ancestor(a, b, seen=None):
    seen = seen or set()
    for x, y in parent:
        if x == a and y not in seen:
            if y == b or ancestor(y, b, seen | {y}): return True
    return False
print('ancestor(ann, cat):', ancestor('ann', 'cat'))
