def bf(prog):
    tape, p, out, jumps, stack = [0]*300, 0, [], {}, []
    for i, c in enumerate(prog):
        if c == '[': stack.append(i)
        elif c == ']':
            j = stack.pop(); jumps[j] = i; jumps[i] = j
    i = 0
    while i < len(prog):
        c = prog[i]
        if c == '>': p += 1
        elif c == '<': p -= 1
        elif c == '+': tape[p] = (tape[p]+1) % 256
        elif c == '-': tape[p] = (tape[p]-1) % 256
        elif c == '.': out.append(chr(tape[p]))
        elif c == '[' and tape[p] == 0: i = jumps[i]
        elif c == ']' and tape[p] != 0: i = jumps[i]
        i += 1
    return ''.join(out)
print('brainfuck output:', bf('++++++++[>++++++++<-]>+.---.'))
